ins as (
  insert into events (venue_id,title,starts_at,time_known,kind,genres,source_url,status,origin)
  select v.id, d.title, d.st, true, 'club', array[d.genre], d.url, 'published', 'manual'
  from d join venues v on v.name=d.vname
  where not exists (select 1 from events e where e.venue_id=v.id and (e.starts_at at time zone 'Europe/Berlin')::date=(d.st at time zone 'Europe/Berlin')::date
     and (e.source_url=d.url and d.url like '%/event/%' or private.norm(e.title)=private.norm(d.title)))
  returning id, title, starts_at, venue_id),
lins as (
  insert into event_lineup (event_id,position,name)
  select i.id, (x.ord-1)::int, x.name from ins i join venues v on v.id=i.venue_id join d on d.title=i.title and d.st=i.starts_at and d.vname=v.name
  cross join lateral jsonb_array_elements_text(d.lu) with ordinality x(name,ord)
  returning 1)
select (select count(*) from d) quelle, (select count(*) from ins) neu, (select count(*) from lins) lineup,
 (select string_agg(distinct d.vname, ', ') from d left join venues v on v.name=d.vname where v.id is null) unbekannt;